// Forensic Science Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: postmortem changes, evidence handling and interpreting results.
import {q, mix} from './q.js';
const BERT='Bertino & Bertino, Forensic Science Fundamentals', BELL='Bell, Forensic Science';
const HIST='Forensic History and Careers', SCENE='Crime Scene and Death Investigation', TOX='Forensic Toxicology and Pharmacology', ANTH='Forensic Anthropology', ENT='Forensic Entomology', BLOOD='Identification of Blood, Bloodstains, Biological Fluids and Stains', DNA='Techniques of DNA Analysis', PSY='Forensic Psychology and Psychiatry';

export default {
 id:'forensic-science-1',
 event:'Forensic Science',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Bertino’s Forensic Science Fundamentals and Bell’s Forensic Science',
 plan:[{area:HIST,weight:10},{area:SCENE,weight:20},{area:TOX,weight:20},{area:ANTH,weight:10},{area:ENT,weight:10},{area:BLOOD,weight:10},{area:DNA,weight:10},{area:PSY,weight:10}],
 questions:mix([
  q(HIST,'Which principle states that every contact leaves a trace?','Locard’s exchange principle',['The Daubert standard','The Frye rule','Bertillon’s system'],'B','Edmond Locard proposed that a criminal leaves something at a scene and takes something away, the basis of trace evidence analysis.',BERT),
  q(HIST,'Alphonse Bertillon developed an early identification system based on:','Body measurements',['Fingerprints','DNA profiles','Dental records'],'D','Bertillonage (anthropometry) used precise body measurements. It was replaced by fingerprinting, which is more reliable.',BERT),
  q(HIST,'Which specialist identifies human remains using teeth and analyzes bite marks?','Forensic odontologist',['Forensic entomologist','Forensic anthropologist','Toxicologist'],'A','Dental records are durable and individual, so odontologists can identify remains even when other methods fail.',BERT),
  q(HIST,'How does a medical examiner usually differ from a coroner?','A medical examiner is a physician',['A medical examiner is always elected','A coroner must be a forensic pathologist','A coroner works only in labs'],'C','Coroners are often elected and may not have medical training. Medical examiners are physicians, usually forensic pathologists, who perform autopsies.',BELL),
  q(HIST,'Which court standard requires judges to evaluate whether scientific evidence is reliable and based on tested methods?','The Daubert standard',['Locard’s principle','The chain of custody','The exclusionary rule'],'B','Under Daubert, judges consider testing, peer review, error rates and acceptance of a method before admitting expert testimony.',BELL),
  q(SCENE,'What is the first priority of the first officer to arrive at a crime scene?','Safety and aid to the injured',['Collecting fingerprints quickly','Photographing the scene','Interviewing witnesses'],'D','Safety and medical aid come first; then the officer secures the scene and limits access to preserve evidence.',BERT),
  q(SCENE,'What does the chain of custody document?','Everyone who handled a piece of evidence, and when',['The order in which suspects were arrested','The evidence’s market value','The judge’s ruling on the case'],'A','An unbroken chain of custody shows the evidence was not lost, altered or contaminated, so it can be used in court.',BERT),
  q(SCENE,'Which search pattern is best for a large outdoor area with many searchers?','Line (strip) search',['Spiral search by one person','Zone search of a single room','Wheel search'],'C','Searchers walk side by side in straight lines across the area. Grid searches repeat the line search at right angles for more thoroughness.',BERT),
  q(SCENE,'Livor mortis becomes fixed, meaning it no longer shifts when the body is moved, at about what time after death?','8 to 12 hours',['30 minutes','2 hours','3 days'],'B','Blood settles by gravity into the lowest parts of the body. Fixed lividity in a pattern that does not match the body’s position suggests the body was moved.',BERT),
  q(SCENE,'Which statement about rigor mortis is generally correct?','It peaks near 12 hours, then fades',['It begins within seconds and lasts a week','It never affects the small muscles','It appears only in cold weather'],'D','Rigor usually starts in small muscles within a few hours, peaks around 12 hours and then fades. Temperature and activity before death affect timing.',BERT),
  q(SCENE,'About how fast does a body cool after death under typical conditions?','About 1.5 °F per hour',['About 10 °F per hour','About 0.1 °F per day','It warms for 12 hours first'],'A','Algor mortis is a rough guide to time since death; clothing, body size and surroundings change the rate.',BERT),
  q(SCENE,'Which is a manner of death, rather than a cause of death?','Homicide',['Gunshot wound','Heart attack','Blood loss'],'C','The five manners are natural, accident, suicide, homicide and undetermined. The cause is the injury or disease that started the chain of events.',BELL),
  q(SCENE,'A victim is shot and dies from blood loss. What is the mechanism of death?','Exsanguination',['The gunshot wound','Homicide','Murder'],'B','The cause is the gunshot wound, the mechanism is exsanguination, and the manner is homicide.',BELL),
  q(SCENE,'Why are wet biological items, such as bloody clothing, packaged in paper rather than plastic?','Plastic traps moisture',['Plastic bags are too expensive','Paper makes evidence heavier','Plastic changes the blood type'],'D','Items are air-dried and packaged in paper, which breathes. Moisture in plastic allows bacteria and mold to destroy the evidence.',BERT),
  q(SCENE,'Tiny red spots in the whites of a victim’s eyes may suggest which cause of death?','Asphyxia',['Arsenic poisoning','A gunshot wound','A fall from a height'],'A','Petechial hemorrhages form when pressure ruptures small vessels, as in strangulation, though they can have other causes.',BELL),
  q(TOX,'In toxicology, what does LD50 describe?','The dose that kills half of a test population',['The legal limit of a drug in blood','The time a drug takes to leave the body','The smallest dose that has any effect'],'C','LD50 compares the toxicity of substances; a lower LD50 means a more toxic substance.',BELL),
  q(TOX,'Which method is used to confirm the identity of a drug after a positive screening test?','GC-MS',['A color spot test','Visual inspection only','A breath test'],'B','Screening tests are presumptive and can give false positives. GC-MS separates and identifies compounds with high certainty.',BELL),
  q(TOX,'A body shows bright cherry-red lividity. Which poisoning is suggested?','Carbon monoxide',['Chronic arsenic','Opioid narcotics','Alcohol'],'D','Carbon monoxide binds tightly to hemoglobin and forms carboxyhemoglobin, which gives the blood and lividity a cherry-red color.',BELL),
  q(TOX,'Pinpoint pupils and slow breathing in an unresponsive person suggest overdose with which type of drug?','An opioid',['A stimulant','A hallucinogen','An inhalant'],'A','Opioids constrict pupils and depress breathing. Stimulants such as cocaine usually dilate the pupils.',BELL),
  q(TOX,'In most U.S. states, what blood alcohol concentration is the legal limit for adult drivers?','0.08%',['0.01%','0.20%','0.50%'],'C','At 0.08% BAC, adult drivers are legally impaired. Commercial drivers have lower limits, and many states have zero tolerance for minors.',BERT),
  q(TOX,'Why is vitreous humor from the eye useful for postmortem toxicology?','It is protected from decay',['It contains the most blood','It always shows the cause of death','It decomposes first'],'B','The vitreous is isolated from decomposition and contamination, making it useful for alcohol, electrolytes and some drugs.',BELL),
  q(TOX,'Why can hair be tested to show long-term arsenic exposure?','Arsenic is deposited into hair as it grows',['Hair contains the most blood','Hair absorbs arsenic from shampoo','Arsenic changes hair color immediately'],'D','Hair grows about 1 cm per month, so segments can reveal exposure over time, helping show chronic poisoning.',BELL),
  q(TOX,'Which statement describes a Schedule I controlled substance?','High potential for abuse with no accepted medical use',['Low abuse potential and sold over the counter','Accepted medical use with moderate abuse risk','Used only in veterinary medicine'],'A','Schedule I drugs, such as heroin, have no currently accepted medical use in the U.S. Schedule II drugs have a high abuse potential but accepted uses.',BERT),
  q(TOX,'Which specimen can show drug use over the longest time period?','Hair',['Blood','Saliva','Breath'],'C','Drugs are detectable in blood and saliva for hours to days, and in urine for days, but in hair for months.',BELL),
  q(TOX,'A victim had a bitter almond odor noted at autopsy. Which poison is suggested?','Cyanide',['Carbon monoxide','Lead','Arsenic'],'B','Cyanide blocks cells from using oxygen. Not everyone can smell its almond-like odor.',BELL),
  q(ANTH,'Which part of the skeleton is most reliable for estimating sex in an adult?','Pelvis',['Femur length alone','Ribs','Hand bones'],'D','The female pelvis is wider with a larger subpubic angle and rounder inlet, adapted for childbirth.',BERT),
  q(ANTH,'How do forensic anthropologists estimate the age of a teenager’s skeleton?','By growth plate fusion',['By the color of the bones','By counting the number of bones','By the weight of the skull'],'A','Growth plates fuse in a predictable order during adolescence and early adulthood, giving an age range.',BERT),
  q(ANTH,'Which bone is commonly used to estimate a person’s height?','Femur',['Clavicle','Patella','Sternum'],'C','Long bones, especially the femur, have length formulas that estimate living stature.',BERT),
  q(ANTH,'A bone fracture shows a bent, “green bone” pattern with signs of a fresh break. What does this suggest?','The injury happened around the time of death',['The bone broke years after death','The fracture healed long before death','The bone was burned'],'B','Fresh (perimortem) bone bends and splinters like a green branch. Dry, postmortem bone breaks with sharp, squared edges.',BELL),
  q(ANTH,'Which skeletal features help forensic anthropologists estimate ancestry?','Features of the skull and face',['The number of ribs','The length of the toes','The shape of the patella'],'D','Skull features such as nasal opening and face shape give clues, though estimates are probabilistic and can be imprecise.',BERT),
  q(ENT,'Which insects are usually the first to arrive at a dead body?','Blowflies',['Beetles','Ants','Moths'],'A','Blowflies can arrive within minutes and lay eggs in wounds and natural openings. Beetles usually arrive later.',BELL),
  q(ENT,'What is the correct order of the blowfly life cycle?','Egg, larva, pupa, adult',['Larva, egg, adult, pupa','Pupa, egg, larva, adult','Egg, pupa, larva, adult'],'C','Larvae (maggots) go through three instars before pupating. The stage found on a body helps estimate time since death.',BELL),
  q(ENT,'How do forensic entomologists use temperature to estimate time since death?','By calculating accumulated degree hours for insect development',['By measuring the body’s temperature only','By counting the number of insects','By noting the weather on the day the body was found'],'B','Insect development depends on heat over time. Weather data and lab growth rates allow a minimum postmortem interval to be estimated.',BELL),
  q(ENT,'How do cooler temperatures affect insect development on a body?','They slow development',['They speed development','They have no effect','They make insects grow larger'],'D','Insects are cold-blooded, so cooler conditions delay each life stage, and very cold weather may stop activity.',BELL),
  q(ENT,'Insects found on a body are a species that lives only in another region. What may this indicate?','The body was moved after death',['The person died of old age','The insects are harmless','The time of death was exactly noon'],'A','Insects from a different habitat suggest the body was moved, which can be important to an investigation.',BELL),
  q(BLOOD,'In the Kastle-Meyer test, what result suggests blood is present?','A pink color',['A blue color','A green glow','No color change'],'C','Phenolphthalein turns pink when hemoglobin catalyzes the reaction with hydrogen peroxide. It is presumptive, not confirmatory.',BERT),
  q(BLOOD,'Why is luminol useful at crime scenes?','It glows with traces of blood',['It identifies the person the blood came from','It dries wet blood stains instantly','It removes blood from fabric'],'B','Luminol produces chemiluminescence with the iron in hemoglobin, revealing hidden or cleaned stains. It is presumptive.',BERT),
  q(BLOOD,'A bloodstain is 1 cm wide and 2 cm long. Using sin θ = width ÷ length, what was the angle of impact?','30 degrees',['45 degrees','60 degrees','90 degrees'],'D','sin θ = 1 ÷ 2 = 0.5, and the angle whose sine is 0.5 is 30°. A round stain indicates about 90°.',BERT),
  q(BLOOD,'Blood flung from a swinging weapon creates which type of pattern?','Cast-off',['Pooling','Transfer','Passive drip'],'A','Cast-off forms lines of drops that can show the direction and number of swings.',BERT),
  q(BLOOD,'Which presumptive test is used to screen for semen?','Acid phosphatase test',['Kastle-Meyer test','Luminol test','Benzidine test'],'C','Semen contains high levels of acid phosphatase. Confirmation uses tests such as PSA or finding sperm under the microscope.',BERT),
  q(DNA,'What does CODIS, the FBI’s DNA database, mainly compare?','STR profiles',['Mitochondrial genomes','ABO blood types','Fingerprint patterns'],'B','STRs are short DNA sequences repeated a variable number of times. CODIS uses 20 core STR loci.',BELL),
  q(DNA,'Why is mitochondrial DNA useful for old bones or hair shafts without roots?','Cells hold many copies of it',['It is unique to every single person','It is found only in the nucleus','It comes only from the father'],'D','Hundreds of copies per cell mean mtDNA often survives when nuclear DNA does not. Relatives on the maternal line share it.',BELL),
  q(DNA,'What is the purpose of PCR in forensic DNA analysis?','To copy small DNA samples',['To cut DNA into small pieces','To determine blood type','To separate DNA by size'],'A','PCR amplifies the target regions so tiny or degraded samples can be profiled.',BELL),
  q(DNA,'Which DNA test traces the male (paternal) line and is useful in mixtures with female DNA?','Y-STR analysis',['Mitochondrial DNA analysis','ABO typing','Serology'],'C','Y-STRs are on the Y chromosome, passed from father to son. They can isolate the male contributor in a sexual assault mixture.',BELL),
  q(DNA,'Why do analysts change gloves frequently when collecting DNA evidence?','To avoid transferring DNA between items',['To keep their hands warm','Because gloves expire quickly','To make the evidence heavier'],'B','Even skin cells left by touching (touch DNA) can contaminate evidence. Frequent glove changes and masks reduce contamination.',BERT),
  q(PSY,'What does competency to stand trial evaluate?','Whether they can understand and assist in their trial',['Whether the defendant was sane at the time of the crime','Whether the defendant is guilty','Whether the defendant has a criminal record'],'D','Competency concerns the defendant’s current mental state. Insanity concerns their mental state at the time of the offense.',BELL),
  q(PSY,'Under the M’Naghten rule, a defendant may be found not guilty by reason of insanity if, due to mental illness, they:','Did not know the act was wrong',['Felt sorry after the crime ended','Had a difficult childhood','Were under the influence of alcohol'],'A','M’Naghten focuses on whether a mental disease prevented the person from understanding what they did or that it was wrong.',BELL),
  q(PSY,'Criminal profilers describe an offender who plans carefully and leaves little evidence as:','Organized',['Disorganized','Impulsive','Reactive'],'C','Organized offenders tend to plan and control the scene. Disorganized offenders act impulsively and leave a chaotic scene.',BELL),
  q(PSY,'Why is eyewitness identification sometimes unreliable?','Stress, weapon focus and suggestion can distort memory',['Memory works like a perfect video recording','Witnesses always remember faces correctly','Lighting has no effect on memory'],'B','Memory is reconstructive. Stress, weapons, poor lighting and leading questions can lead to confident but wrong identifications.',BELL),
  q(PSY,'Which tool is widely used to assess psychopathy in forensic settings?','The PCL-R',['The Glasgow Coma Scale','APGAR score','Snellen chart'],'D','The PCL-R rates traits such as superficial charm, lack of remorse and impulsivity, and is used in risk assessment.',BELL)
 ],149)
};
